import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/cpu_verify.B269LQ3y.png",r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"调试接口","link":"/api/SIMD-API/basic_api/debug_interface/debug_interface"},{"text":"CPU孪生调试","link":"/api/SIMD-API/basic_api/debug_interface/cpu_twin_debug/cpu_twin_debug"},{"text":"ICPU_RUN_KF","link":"/api/SIMD-API/basic_api/debug_interface/cpu_twin_debug/ICPU_RUN_KF"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/debug_interface/cpu_twin_debug/ICPU_RUN_KF.md","filePath":"api/SIMD-API/basic_api/debug_interface/cpu_twin_debug/ICPU_RUN_KF.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),t={name:"api/SIMD-API/basic_api/debug_interface/cpu_twin_debug/ICPU_RUN_KF.md"};function i(e,s,d,o,_,u){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>ICPU_RUN_KF<span id="ZH-CN_TOPIC_0000002080882157"></span></h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<span id="zh-cn_topic_0000001963799134_zh-cn_topic_0000001541924164_section259105813316"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tools/cpudebug/include/kern_fwk.h&quot;</code>。</p><p>进行核函数（Kernel）的CPU侧运行验证时，CPU调测总入口，完成CPU侧的算子程序调用。</p><h2 id="函数原型">函数原型<span id="zh-cn_topic_0000001963799134_zh-cn_topic_0000001541924164_section2067518173415"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#define ICPU_RUN_KF(func, numBlocks, ...)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="zh-cn_topic_0000001963799134_zh-cn_topic_0000001541924164_section158061867342"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>func</td><td>输入</td><td>算子的kernel函数指针。</td></tr><tr><td>numBlocks</td><td>输入</td><td>算子的核心数，corenum。</td></tr><tr><td>...</td><td>输入</td><td>所有的入参和出参，依次填入，当前参数个数限制为32个，超出32时会出现编译错误。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="zh-cn_topic_0000001963799134_zh-cn_topic_0000001541924164_section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000001963799134_zh-cn_topic_0000001541924164_section794123819592"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>为了保留接口兼容，推荐<a href="../../../../../guide/programming_guide/debug_and_tuning/functional_debug/cpu_twin_debug.html">&lt;&lt;&lt;&gt;&gt;&gt;</a>编译使用。</li><li>除了func、blkdim以外，其他的变量都必须是通过<a href="GmAlloc.html">GmAlloc</a>分配的共享内存的指针；传入的参数的数量和顺序都必须和kernel保持一致。</li></ul><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000001963799134_zh-cn_topic_0000001541924164_section82241477610"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>下面代码以add_custom算子为例，介绍算子核函数（Kernel）在CPU侧验证时，算子调用的应用程序如何编写。您在实现自己的应用程序时，需要关注由于算子核函数（Kernel）不同带来的修改，包括算子核函数（Kernel）名，入参出参的不同等，合理安排相应的内存分配、内存拷贝和文件读写等，相关API的调用方式直接复用即可。</p><ol><li><p>按需包含头文件，通过ASCENDC_CPU_DEBUG宏区分CPU和NPU侧需要包含的头文件。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;data_utils.h&quot;</span>
<span class="cp">#ifndef ASCENDC_CPU_DEBUG</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;acl/acl.h&quot;</span>
<span class="cp">#else</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tikicpulib.h&quot;</span>
<span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">);</span><span class="w"> </span><span class="c1">// 核函数（Kernel）声明。</span>
<span class="cp">#endif</span>
</code></pre></div></li><li><p>CPU侧运行验证。完成算子核函数（Kernel）CPU侧运行验证的步骤如下：</p><p><strong>图1</strong> CPU侧运行验证步骤<span id="fig13576112114442"></span><br><img src="`+c+`" alt title="CPU侧运行验证步骤"></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">int32_t</span><span class="w"> </span><span class="nf">main</span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">argc</span><span class="p">,</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">argv</span><span class="p">[])</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">numBlocks</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="w">    </span><span class="kt">size_t</span><span class="w"> </span><span class="n">inputByteSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2048</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">uint16_t</span><span class="p">);</span>
<span class="w">    </span><span class="kt">size_t</span><span class="w"> </span><span class="n">outputByteSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2048</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">uint16_t</span><span class="p">);</span>

<span class="w">   </span><span class="c1">// 使用GmAlloc分配共享内存，并进行数据初始化。</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="kt">uint8_t</span><span class="o">*</span><span class="p">)</span><span class="n">AscendC</span><span class="o">::</span><span class="n">GmAlloc</span><span class="p">(</span><span class="n">inputByteSize</span><span class="p">);</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="kt">uint8_t</span><span class="o">*</span><span class="p">)</span><span class="n">AscendC</span><span class="o">::</span><span class="n">GmAlloc</span><span class="p">(</span><span class="n">inputByteSize</span><span class="p">);</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="kt">uint8_t</span><span class="o">*</span><span class="p">)</span><span class="n">AscendC</span><span class="o">::</span><span class="n">GmAlloc</span><span class="p">(</span><span class="n">outputByteSize</span><span class="p">);</span>

<span class="w">    </span><span class="n">ReadFile</span><span class="p">(</span><span class="s">&quot;./input/input_x.bin&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">inputByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">inputByteSize</span><span class="p">);</span>
<span class="w">    </span><span class="n">ReadFile</span><span class="p">(</span><span class="s">&quot;./input/input_y.bin&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">inputByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">inputByteSize</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 矢量算子需要设置内核模式为AIV模式。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetKernelMode</span><span class="p">(</span><span class="n">KernelMode</span><span class="o">::</span><span class="n">AIV_MODE</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 调用ICPU_RUN_KF调测宏，完成核函数（Kernel）CPU侧的调用。</span>
<span class="w">    </span><span class="n">ICPU_RUN_KF</span><span class="p">(</span><span class="n">add_custom</span><span class="p">,</span><span class="w"> </span><span class="n">numBlocks</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 输出数据写出。</span>
<span class="w">    </span><span class="n">WriteFile</span><span class="p">(</span><span class="s">&quot;./output/output_z.bin&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">outputByteSize</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 调用GmFree释放申请的资源。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GmFree</span><span class="p">((</span><span class="kt">void</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">x</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GmFree</span><span class="p">((</span><span class="kt">void</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">y</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GmFree</span><span class="p">((</span><span class="kt">void</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">z</span><span class="p">);</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></li></ol></article></div>`,1)])])}const w=a(t,[["render",i]]);export{r as __pageData,w as default};
